                    }
                }
                {
                    \time 1/5
                    \times 4/5 {
                        c'4
                    }
                }
                {
                    \time 3/4
                    {
                        c'2.
                    }
                }
            }

    Usage follows the two-step configure-then-call pattern shown here.
    '''

    ### CLASS VARIABLES ###

    __slots__ = (
