            flattened_rewards = torch.flatten(batch_stats.logged_rewards).tolist()
            self.running_reward.extend(flattened_rewards)

        if batch_stats.reward_loss is not None:
            reward_loss_mean = float(batch_stats.reward_loss.mean())
