def restcheck(path):
    try:
        import docutils
    except ImportError:
        py.test.skip("docutils not importable")
    rest.process(path)
    check_htmllinks(path) 
    #assert not out

def test_rest_files():
    for x in docdir.listdir('*.txt'):
        yield restcheck, x

